 terms(){return heading('学期与校历','当前展示学期与可操作状态分别设置，时间边界清楚可见。',button(`${icon('plus')}新建学期`,'new-term',true))+`<div class="grid two">${panel('2026—2027 学年 · 第一学期',`<div class="form-grid">${field('学年',input('academic-year','2026—2027'))}${field('学期',select('semester',['第一学期','第二学期']))}${field('开始日期',input('term-start','2026-09-01','','date'))}${field('结束日期',input('term-end','2027-01-31','','date'))}${field('学校时区',select('timezone',['Asia/Shanghai','Asia/Hong_Kong','UTC']))}${field('宽限期截止（日）',input('grace',3,'','number','min="1" max="31"'),'SPEC 示例为次月3日，最终按校方配置。')}${field('故事提交截止',input('story-deadline','2026-10-28','','date'))}${field('发卡截止',input('card-deadline','2026-10-31','','date'))}${field('学期审核截止',input('review-deadline','2027-01-25','','date'))}${field('报告计划发布日',input('publish-date','2027-01-28','','date'))}</div><div class="spacer"></div><div class="inline-list"><label class="small"><input type="checkbox" checked name="is-current"> 设为默认展示学期</label><label class="small" style="margin-left:16px"><input type="checkbox" ${state.archive?'':'checked'} name="term-active"> 允许正常业务操作</label></div><div class="form-footer">${button('预览归档说明','archive-term')}${button('校验并保存','save-term',true)}</div>`)}${panel('校历节奏',`<div class="timeline"><div class="timeline-item"><i class="timeline-dot"></i><div><div class="timeline-title">第 8 教学周</div><div class="timeline-date">10.19 — 10.25 · 当前周</div></div></div><div class="timeline-item"><i class="timeline-dot hollow"></i><div><div class="timeline-title">十月故事提交</div><div class="timeline-date">10.28 截止</div></div></div><div class="timeline-item"><i class="timeline-dot hollow"></i><div><div class="timeline-title">十月评价卡失效</div><div class="timeline-date">10.31 23:59</div></div></div><div class="timeline-item"><i class="timeline-dot hollow"></i><div><div class="timeline-title">十月已申领卡宽限截止</div><div class="timeline-date">11.03 23:59 · 试行示例</div></div></div></div><div class="spacer"></div>${button('编辑教学周与假期','calendar-edit')}`)}</div>`},
