 if(action==='generic-form-save'){if(!val('reason'))return modalFormError('请填写具体原因。');closeModal();demo('已完成表单校验和交互演示，未执行真实业务操作。');return}
 if(action==='retry-demo'){closeModal();demo('已展示重试操作入口，原型未向任何外部渠道投递消息。');return}
 if(content[action]){const [title,body]=content[action];const hasFooter=body.includes('form-footer');openModal(title,body+(hasFooter?'':`<div class="form-footer">${button('关闭','close-modal')}${['new-term','calendar-edit','new-account','account-permissions','category-new','story-task'].includes(action)?button('预览表单校验','design-form-check',true):''}</div>`));return}
 if(action==='design-form-check'){toast('该表单为设计演示；正式版依服务端契约校验和保存。');return}
 demo();
