document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.modal)closeModal();$('.sidebar.open')?.classList.remove('open');$('.mobile-shade.show')?.classList.remove('show')}if(e.key==='Tab'&&state.modal){const focusable=$$('.modal button:not([disabled]),.modal input:not([disabled]),.modal select:not([disabled]),.modal textarea:not([disabled]),.modal a');const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
